import { useMemo } from 'react';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useGetCstmrWalletListQuery } from '~/entities/user/api/use-get-cstmr-wallet-list-query';
import { YesOrNo } from '~/shared/api/dtos/enums';
import { findTokenItemByAliasNm } from './wallet-utils';

type UseSelectedWalletAutoOnRampParams = {
  aliasNm?: string | null;
};

export const useSelectedWalletAutoOnRamp = ({ aliasNm }: UseSelectedWalletAutoOnRampParams = {}) => {
  const { data: userRes } = useGetUserInfoQuery();
  const { data: walletList = [] } = useGetCstmrWalletListQuery();

  const selectedAliasNm = aliasNm ?? userRes?.tbCstmrMastr?.aliasNm ?? userRes?.tbCstmrMastr?.dfltAliasNm ?? undefined;

  const selectedWallet = useMemo(() => {
    if (!selectedAliasNm) {
      return null;
    }

    return findTokenItemByAliasNm(walletList, selectedAliasNm);
  }, [walletList, selectedAliasNm]);

  const autoOnRamp =
    (selectedWallet?.dc1AtmcOnrampYn as YesOrNo | null | undefined) ??
    (userRes?.tbCstmrMastr?.dc1AtmcOnrampYn as YesOrNo | null | undefined) ??
    YesOrNo.아니오;

  return {
    autoOnRamp,
    selectedAliasNm,
    selectedWallet,
  };
};
